import java.util.ArrayList;

public class Registro {

    // Atributos
    // Guarda los listados del sistema
    // Incluye las oficinas, dispositivos, alertas,
    // facturas, severidades y la bandeja de alertas

    private ArrayList<Oficina> oficinas;
    private ArrayList<Dispositivo> dispositivos;
    private ArrayList<Alerta> alertas;
    private ArrayList<Factura> facturas;
    private ArrayList<Severidad> severidades;
    private BandejaAlertas bandeja;


    // Constructor vacio
    // Inicializa los listados y la bandeja
    // Agrega las tres severidades predeterminadas

    public Registro() {
        oficinas = new ArrayList<Oficina>();
        dispositivos = new ArrayList<Dispositivo>();
        alertas = new ArrayList<Alerta>();
        facturas = new ArrayList<Factura>();
        severidades = new ArrayList<Severidad>();
        bandeja = new BandejaAlertas();

        // Severidades default, las crea de una
        severidades.add(new Severidad(1, "Baja", 1, 24, 0.50));
        severidades.add(new Severidad(2, "Alta", 2, 4, 2.00));
        severidades.add(new Severidad(3, "Critica", 3, 1, 5.00));
    }


    // Registrar oficina

    public boolean registrarOficina(Oficina oficina) {

        if (oficina == null) {
            return false;
        }

        if (oficina.getCodigo() == null || oficina.getCodigo().isEmpty()) {
            return false;
        }

        if (oficina.getInquilino() == null || oficina.getInquilino().isEmpty()) {
            return false;
        }

        // Evita codigos repetidos
        if (buscarOficina(oficina.getCodigo()) != null) {
            return false;
        }

        oficinas.add(oficina);
        return true;
    }


    // Buscar oficina
    public Oficina buscarOficina(String codigo) {

        if (codigo == null) {
            return null;
        }

        for (Oficina oficina : oficinas) {
            if (oficina.getCodigo().equals(codigo)) {
                return oficina;
            }
        }

        return null;
    }


    // Registrar dispositivo
    public boolean registrarDispositivo(Dispositivo dispositivo) {

        if (dispositivo == null) {
            return false;
        }

        if (dispositivo.getCodigo() == null || dispositivo.getCodigo().isEmpty()) {
            return false;
        }

        if (dispositivo.getOficina() == null) {
            return false;
        }

        if (dispositivo.getPotenciaNominal() <= 0 || Double.isNaN(dispositivo.getPotenciaNominal()) || Double.isInfinite(dispositivo.getPotenciaNominal())) {
            return false;
        }

        // Comprueba que no exista otro dispositivo con el mismo codigo
        if (buscarDispositivo(dispositivo.getCodigo()) != null) {
            return false;
        }

        // Busca la oficina correspondiente
        Oficina oficina = buscarOficina(dispositivo.getOficina().getCodigo());

        if (oficina == null) {
            return false;
        }

        // Comprueba que sea la misma oficina registrada
        if (oficina != dispositivo.getOficina()) {
            return false;
        }

        dispositivos.add(dispositivo);
        return true;
    }


    // Buscar dispositivo
    public Dispositivo buscarDispositivo(String codigo) {

        if (codigo == null) {
            return null;
        }

        for (Dispositivo dispositivo : dispositivos) {
            if (dispositivo.getCodigo().equals(codigo)) {
                return dispositivo;
            }
        }

        return null;
    }


    // Buscar severidad
    public Severidad buscarSeveridad(int tipo) {

        for (Severidad severidad : severidades) {
            if (severidad.getTipo() == tipo) {
                return severidad;
            }
        }

        return null;
    }


    // Registrar alerta (despues de comprobar si todo es valido)
    public boolean registrarAlerta(Alerta alerta) {

        if (alerta == null) {
            return false;
        }

        if (alerta.getCodigo() <= 0 || alerta.getAtendida()) {
            return false;
        }

        if (alerta.getDispositivo() == null || alerta.getSeveridad() == null) {
            return false;
        }

        // Comprueba que el dispositivo este registrado
        Dispositivo dispositivo = buscarDispositivo(alerta.getDispositivo().getCodigo());

        if (dispositivo != alerta.getDispositivo()) {
            return false;
        }

        // Comprueba que la severidad este registrada
        Severidad severidad = buscarSeveridad(alerta.getSeveridad().getTipo());

        if (severidad != alerta.getSeveridad()) {
            return false;
        }

        // Evita codigos de alerta repetidos
        for (Alerta registrada : alertas) {
            if (registrada.getCodigo() == alerta.getCodigo()) {
                return false;
            }
        }

        // Primero agrega a la bandeja
        // Si falla, no modifica el historial
        if (!bandeja.agregarAlerta(alerta)) {
            return false;
        }

        alertas.add(alerta);
        return true;
    }


    // Registrar factura
    public void registrarFactura(Factura factura) {
		//Codigo y pertenecce a una oficina

        if (factura == null || factura.getOficina() == null) {
            return;
        }

        Oficina oficina = buscarOficina(factura.getOficina().getCodigo());

        if (oficina != factura.getOficina()) {
            return;
        }

        // Evita guardar dos facturas del mismo dia y oficina
        for (Factura registrada : facturas) {
            if (registrada.getOficina() == oficina && registrada.getDia() == factura.getDia()) {
                return;
            }
        }

        facturas.add(factura);
    }


    // Getters
    public BandejaAlertas getBandeja() {
        return bandeja;
    }

    public ArrayList<Oficina> getOficinas() {
        return new ArrayList<Oficina>(oficinas);
    }

    public ArrayList<Dispositivo> getDispositivos() {
        return new ArrayList<Dispositivo>(dispositivos);
    }

    public ArrayList<Alerta> getAlertas() {
        return new ArrayList<Alerta>(alertas);
    }

    public ArrayList<Factura> getFacturas() {
        return new ArrayList<Factura>(facturas);
    }
}
